/*! coi-serviceworker v0.1.7 - Guido Zuidhof and contributors, licensed under MIT */
/* CodeLab addition: serve manually preloaded browsercc assets from Cache Storage. */
const COMPILER_CACHE_NAME = "codelab-compiler-assets-v1";
const COMPILER_CDN_PREFIX = "https://cdn.jsdelivr.net/npm/browsercc@0.1.1/dist/";
let coepCredentialless = false;

if (typeof window === "undefined") {
  self.addEventListener("install", () => self.skipWaiting());
  self.addEventListener("activate", (event) => event.waitUntil(self.clients.claim()));

  self.addEventListener("message", (event) => {
    if (!event.data) return;
    if (event.data.type === "deregister") {
      self.registration.unregister()
        .then(() => self.clients.matchAll())
        .then((clients) => clients.forEach((client) => client.navigate(client.url)));
    } else if (event.data.type === "coepCredentialless") {
      coepCredentialless = event.data.value;
    }
  });

  self.addEventListener("fetch", (event) => {
    const request = event.request;
    if (request.cache === "only-if-cached" && request.mode !== "same-origin") return;

    const outgoingRequest = (coepCredentialless && request.mode === "no-cors")
      ? new Request(request, { credentials: "omit" })
      : request;

    event.respondWith((async () => {
      let response = null;
      const isCompilerAsset = request.method === "GET" && request.url.startsWith(COMPILER_CDN_PREFIX);

      // The Download Compiler button writes these exact CDN URLs to Cache Storage.
      // Serve those bytes to the compiler worker instead of downloading them again.
      if (isCompilerAsset) {
        try {
          const cache = await caches.open(COMPILER_CACHE_NAME);
          response = await cache.match(request.url);
        } catch (error) {
          console.warn("CodeLab compiler cache could not be read:", error);
        }
      }

      if (!response) response = await fetch(outgoingRequest);
      if (response.status === 0) return response;

      const headers = new Headers(response.headers);
      headers.set("Cross-Origin-Embedder-Policy", coepCredentialless ? "credentialless" : "require-corp");
      if (!coepCredentialless) headers.set("Cross-Origin-Resource-Policy", "cross-origin");
      headers.set("Cross-Origin-Opener-Policy", "same-origin");

      // Cached JS modules and WebAssembly assets are fetched cross-origin by module workers.
      if (isCompilerAsset) headers.set("Access-Control-Allow-Origin", "*");

      return new Response(response.body, {
        status: response.status,
        statusText: response.statusText,
        headers
      });
    })().catch((error) => {
      console.error("CodeLab service worker fetch failed:", error);
      return new Response("CodeLab could not load this resource. Check your connection and reload the page.", {
        status: 503,
        headers: {
          "Content-Type": "text/plain; charset=utf-8",
          "Access-Control-Allow-Origin": "*",
          "Cross-Origin-Resource-Policy": "cross-origin"
        }
      });
    }));
  });
} else {
  (() => {
    const reloadedBySelf = window.sessionStorage.getItem("coiReloadedBySelf");
    window.sessionStorage.removeItem("coiReloadedBySelf");
    const coepDegrading = reloadedBySelf == "coepdegrade";

    const coi = {
      shouldRegister: () => !reloadedBySelf,
      shouldDeregister: () => false,
      coepCredentialless: () => true,
      coepDegrade: () => true,
      doReload: () => window.location.reload(),
      quiet: false,
      ...window.coi
    };

    const n = navigator;
    const controlling = n.serviceWorker && n.serviceWorker.controller;

    if (controlling && !window.crossOriginIsolated) {
      window.sessionStorage.setItem("coiCoepHasFailed", "true");
    }
    const coepHasFailed = window.sessionStorage.getItem("coiCoepHasFailed");

    if (controlling) {
      const reloadToDegrade = coi.coepDegrade() && !(coepDegrading || window.crossOriginIsolated);
      n.serviceWorker.controller.postMessage({
        type: "coepCredentialless",
        value: (reloadToDegrade || (coepHasFailed && coi.coepDegrade()))
          ? false
          : coi.coepCredentialless()
      });
      if (reloadToDegrade) {
        !coi.quiet && console.log("Reloading page to degrade COEP.");
        window.sessionStorage.setItem("coiReloadedBySelf", "coepdegrade");
        coi.doReload("coepdegrade");
      }
      if (coi.shouldDeregister()) n.serviceWorker.controller.postMessage({ type: "deregister" });
    }

    if (window.crossOriginIsolated !== false || !coi.shouldRegister()) return;
    if (!window.isSecureContext) {
      !coi.quiet && console.log("COOP/COEP Service Worker not registered: secure context required.");
      return;
    }
    if (!n.serviceWorker) {
      !coi.quiet && console.error("COOP/COEP Service Worker not registered: browser has no Service Worker support.");
      return;
    }

    n.serviceWorker.register(window.document.currentScript.src).then(
      (registration) => {
        !coi.quiet && console.log("COOP/COEP Service Worker registered", registration.scope);
        registration.addEventListener("updatefound", () => {
          !coi.quiet && console.log("Reloading page to activate updated COOP/COEP Service Worker.");
          window.sessionStorage.setItem("coiReloadedBySelf", "updatefound");
          coi.doReload();
        });
        if (registration.active && !n.serviceWorker.controller) {
          !coi.quiet && console.log("Reloading page so the Service Worker can control it.");
          window.sessionStorage.setItem("coiReloadedBySelf", "notcontrolling");
          coi.doReload();
        }
      },
      (error) => {
        !coi.quiet && console.error("COOP/COEP Service Worker failed to register:", error);
      }
    );
  })();
}
